// Grass blades drawn on the GPU: a fixed lattice of blades that wraps around the camera (each blade stays put in the
// world), standing on a height/density field generated by the workers. Two rings: dense thin blades close by, wider
// sparser blades further out, all shrinking into the ground at the edge. Gusts roll across the meadow and blades part
// around the player's legs.
import * as THREE from 'three';
import { patch, U } from './fx.js';
import { mulberry } from './noise.js';

const FN = 129, FSTEP = 1, FHALF = 64;

function bladeGeometry() {
  // 7 vertices: 3 pairs and a tip; position.x = -0.5..0.5 across, position.y = 0..1 up
  const p = [], ys = [0, .3, .62];
  for (const y of ys) { const w = 1 - y * .55; p.push(-.5 * w, y, 0, .5 * w, y, 0); }
  p.push(0, 1, 0);
  const idx = [0, 1, 2, 1, 3, 2, 2, 3, 4, 3, 5, 4, 4, 5, 6];
  const g = new THREE.InstancedBufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3)); g.setIndex(idx);
  g.setAttribute('normal', new THREE.Float32BufferAttribute(new Array(21).fill(0).map((_, i) => i % 3 === 1 ? 1 : 0), 3));
  return g;
}

const VS_HEAD = `#include <common>
attribute vec4 aOff; attribute vec4 aRnd;
uniform sampler2D uField; uniform vec4 uFieldO; uniform vec4 uRing; uniform float uTime; uniform vec4 uWind; uniform vec3 uPlayer; uniform float uH; uniform vec4 uFade;
varying vec3 vGCol; varying float vGAo;
vec4 fieldAt( vec2 wp ) {
  vec2 t = ( wp - uFieldO.xy ) / uFieldO.z; vec2 i = floor( t ), f = t - i; ivec2 b = ivec2( i );
  ivec2 m = ivec2( ${FN - 1} );
  vec4 a = texelFetch( uField, clamp( b, ivec2( 0 ), m ), 0 ), c = texelFetch( uField, clamp( b + ivec2( 1, 0 ), ivec2( 0 ), m ), 0 );
  vec4 d = texelFetch( uField, clamp( b + ivec2( 0, 1 ), ivec2( 0 ), m ), 0 ), e = texelFetch( uField, clamp( b + ivec2( 1, 1 ), ivec2( 0 ), m ), 0 );
  return mix( mix( a, c, f.x ), mix( d, e, f.x ), f.y );
}`;
const VS_BODY = `
float T = uRing.w;
vec2 cam = cameraPosition.xz;
vec2 wp = cam + mod( aOff.xy - cam + T * 0.5, T ) - T * 0.5;
float dist = length( wp - cam );
vec4 fd = fieldAt( wp );
float keep = step( aRnd.x, fd.g ) * smoothstep( uFade.x, uFade.y, dist ) * ( 1.0 - smoothstep( uFade.z, uFade.w, dist ) );
float hgt = uH * ( 0.35 + aRnd.y * aRnd.y * 1.1 ) * ( 0.2 + 0.9 * fd.g ) * keep;
float wid = uRing.z * ( 0.7 + aRnd.z * 0.6 );
// face mostly at random, partly toward the camera so blades never vanish edge-on
float ang = aRnd.w * 6.2832;
vec2 rf = vec2( cos( ang ), sin( ang ) ), tc = normalize( cam - wp + 1e-3 );
vec2 face = normalize( mix( rf, tc, 0.45 ) ); vec2 across = vec2( - face.y, face.x );
float y = position.y, y2 = y * y;
// wind: travelling gusts plus flutter
vec2 wd = normalize( uWind.xy + 1e-4 );
float wave = sin( dot( wp, wd ) * 0.21 - uTime * 1.9 ) * 0.5 + 0.5;
float gust = uWind.z * ( 0.35 + 0.65 * wave * wave ) + uWind.z * 0.15 * sin( uTime * 4.1 + aOff.x * 3.1 + aOff.y * 2.3 );
vec2 bend = face * ( 0.12 + aOff.z * 0.25 ) + wd * gust * 0.55;
// part around the player
vec2 away = wp - uPlayer.xz; float pd = length( away ); bend += ( away / max( pd, 1e-3 ) ) * smoothstep( 0.9, 0.0, pd ) * 0.9 * step( abs( uPlayer.y - fd.r ), 2.5 );
vec3 transformed = vec3( wp.x, fd.r + uFieldO.w, wp.y );
transformed.xz += across * position.x * wid;
transformed.xz += bend * y2 * hgt;
transformed.y += y * hgt * ( 1.0 - 0.25 * dot( bend, bend ) );
// colour: dark at the root, lighter toward the tip; dry patches turn straw-coloured
vec3 green = mix( vec3( 0.16, 0.24, 0.06 ), vec3( 0.32, 0.36, 0.12 ), aOff.w );
vec3 dry = vec3( 0.46, 0.41, 0.2 );
vec3 tip = mix( green, dry, smoothstep( 0.4, 0.85, fd.b + aOff.w * 0.25 - 0.1 ) );
vGCol = mix( tip * 0.68, tip * 0.98, y );
vGAo = mix( 0.62, 1.0, y ) * ( 1.0 - 0.4 * fd.a );`;

export class Grass {
  constructor(scene, jobs, opts = {}) {
    this.scene = scene; this.jobs = jobs; this.group = new THREE.Group(); scene.add(this.group);
    const data = new Float32Array(FN * FN * 4), tex = new THREE.DataTexture(data, FN, FN, THREE.RGBAFormat, THREE.FloatType);
    tex.minFilter = tex.magFilter = THREE.NearestFilter; tex.needsUpdate = true;
    this.field = { tex, data, o: { value: new THREE.Vector4(1e6, 1e6, FSTEP, 0) }, ax: 1e9, az: 1e9, job: null, ready: false };
    this.uPlayer = { value: new THREE.Vector3(0, -1e3, 0) };
    this.rings = []; this.build(opts.quality || 'high');
  }
  build(q) {
    for (const r of this.rings) { this.group.remove(r.mesh); r.mesh.geometry.dispose(); r.mesh.material.dispose(); }
    this.rings = [];
    // [inner, outer, blade width, spacing, fade]
    // the far blades are wider than they look thin, so they cover a pixel or more and never shimmer as you move
    const conf = { high: [[0, 16, .046, .1, [-1, 0, 13, 16]], [13, 34, .13, .25, [13, 16, 25, 34]]], medium: [[0, 13, .052, .125, [-1, 0, 10, 13]], [10, 24, .15, .3, [10, 13, 18, 24]]], low: [[0, 14, .075, .22, [-1, 0, 9, 14]]] }[q] || [];
    conf.forEach(([r0, r1, w, sp, fade], k) => this.rings.push(this.ring(r0, r1, w, sp, k, fade)));
    this.quality = q;
  }
  ring(r0, r1, width, spacing, k, fade) {
    const T = r1 * 2, n = Math.floor(T / spacing), count = n * n, R = mulberry(101 + k);
    const off = new Float32Array(count * 4), rnd = new Float32Array(count * 4);
    for (let j = 0, i = 0; j < n; j++) for (let x = 0; x < n; x++, i++) {
      off[i * 4] = (x + R()) * spacing; off[i * 4 + 1] = (j + R()) * spacing; off[i * 4 + 2] = R(); off[i * 4 + 3] = R();
      rnd[i * 4] = R() * .98; rnd[i * 4 + 1] = R(); rnd[i * 4 + 2] = R(); rnd[i * 4 + 3] = R();
    }
    const g = bladeGeometry(); g.setAttribute('aOff', new THREE.InstancedBufferAttribute(off, 4)); g.setAttribute('aRnd', new THREE.InstancedBufferAttribute(rnd, 4)); g.instanceCount = count;
    const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, metalness: 0, side: THREE.DoubleSide });
    const uRing = { value: new THREE.Vector4(r0, r1, width, T) }, uH = { value: .55 }, uFade = { value: new THREE.Vector4(...fade) };
    patch(mat, 'grass', sh => {
      Object.assign(sh.uniforms, { uField: { value: this.field.tex }, uFieldO: this.field.o, uRing, uFade, uTime: U.uTime, uWind: U.uWind, uPlayer: this.uPlayer, uH, uSunCol: U.uSunCol, uSunDirF: U.uSunDirW });
      sh.vertexShader = sh.vertexShader.replace('#include <common>', VS_HEAD).replace('#include <begin_vertex>', VS_BODY)
        .replace('#include <beginnormal_vertex>', 'vec3 objectNormal = vec3( 0.0, 1.0, 0.0 );');
      sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nvarying vec3 vGCol; varying float vGAo; uniform vec3 uSunCol; uniform vec3 uSunDirF;')
        .replace('#include <map_fragment>', 'diffuseColor.rgb = vGCol;')
        .replace('float faceDirection = gl_FrontFacing ? 1.0 : - 1.0;', 'float faceDirection = 1.0;')
        .replace('#include <lights_fragment_end>', `#include <lights_fragment_end>
reflectedLight.indirectDiffuse *= vGAo;
{ vec3 sv = normalize( ( viewMatrix * vec4( uSunDirF, 0.0 ) ).xyz ); float bl = pow( max( dot( - geometryViewDir, sv ), 0.0 ), 2.0 );
  reflectedLight.directDiffuse += diffuseColor.rgb * uSunCol * 0.12 * bl * vGAo; }   // a soft glow through the blades against the sun, not glints`);
    });
    const mesh = new THREE.Mesh(g, mat); mesh.frustumCulled = false; mesh.receiveShadow = true; mesh.castShadow = false; mesh.renderOrder = 1;
    this.group.add(mesh);
    return { mesh, uRing, uH };
  }
  update(cam, player) {
    this.uPlayer.value.copy(player);
    const ax = Math.round(cam.x / 16) * 16, az = Math.round(cam.z / 16) * 16, f = this.field;
    if ((ax !== f.ax || az !== f.az) && !f.job) {
      const x0 = ax - FHALF, z0 = az - FHALF, h0 = this.jobs.world.height(ax, az);
      f.ax = ax; f.az = az;
      const job = this.jobs.run({ t: 'grass', x0, z0, n: FN, step: FSTEP, h0 }, (this.field.ready ? 5 : 0)); f.job = job;
      job.promise.then(r => { if (f.job !== job) return; f.job = null; f.data.set(r); f.tex.needsUpdate = true; f.o.value.set(x0, z0, FSTEP, h0); f.ready = true; });
    }
    this.group.visible = f.ready && this.rings.length > 0;
  }
}
